def taylor_loss(h1,h0,fault=None):
    return (2 if fault=='Taylor' else 8)*h1*h1+16*h0*h0

def capture_loss(radius,fault=None):
    return 0 if fault=='center_transfer' else taylor_loss(radius,radius)

def seed_inputs(ff):
    return inputs({'f':ff},False)

def basin_certificate():
    prior=inherited()
    ss=[IV(c-BASIN_RADIUS,c+BASIN_RADIUS) for c in CENTER]
    e,f,u=inputs(profile_at(F(0),F(0)),True)
    # Outward exported U is a valid inherited upper bound. Recompute fresh
    # slightly wider boxes and their entire residual certificate, so there is
    # no transfer of old bounds to an unjustified larger enclosure.
    U=F(prior['feasible_energy_upper']);eps=U-dual(CENTER,u).a+capture_loss(BASIN_RADIUS)
    assert 0<eps<F(1,10**12)
    boxes=[prof.coordinate_box(n,u[0][n],u[1][n],eps,CENTER[0],CENTER[1]) for n in range(7)]
    # Admission applies to actual global minima and the inherited K2210
    # fixed-squeeze optimizing candidate, not arbitrary low-energy profiles.
    eta=out(C/4*(ss[0]*sqrtiv(boxes[1]/boxes[0])-ss[1]*sqrtiv((1-boxes[1])/(1-boxes[0])))-(aa(ss[0])-aa(ss[1]))/2)
    da=out(aa(ss[0])-aa(ss[1]));kv=out((F(5,4)*ss[0]-(da-3*eta)/C)/ss[1]);cv=out(ss[0]/(4*ss[1])-(da/2+eta)/(C*ss[1]))
    rt=sqrtq(boxes[2].a,bits=300).a
    knlo=kv.a-(ss[0]/ss[1]).b*(1-rt)-max(-cv.a,F(0))/3
    knhi=kv.b+(ss[0]/ss[1]).b/3*(1/rt-1)+max(cv.b,F(0))/3
    assert prof.barrier(knlo,knhi,2,F(1,3),F(1,2))
    L=F(3,20);SIG=F(1,3);RHO=F(2,3)
    for n in [0,1]:
     ratio=sqrtiv((1-boxes[n+1])/(1-boxes[n]));assert ratio.a>SIG and ratio.b<RHO
    assert boxes[0].a>L and boxes[0].b<F(1,5)
    kappa=C*min(ss[0].a*L,ss[1].a*SIG)*(1-RHO**2)**2/32
    ky=complementary_coercivity(kappa,1-boxes[0].b,RHO,ss[1].a)
    def z(n,j):return out(p(n)*(boxes[n] if j==0 else 1-boxes[n]))
    def h(n,j,s):return 0 if n<0 else out(C*s*(n+1)*sqrtiv(z(n,j)*z(n+1,j))/4)
    def coef(m,s):
     diag=[out(sum((h(n-1,j,s[j])+h(n,j,s[j]))/(z(n,j)**2) for j in range(2))) for n in range(m+1)]
     off=[out(-sum(h(n,j,s[j])/(z(n,j)*z(n+1,j)) for j in range(2))) for n in range(m)]
     return diag,off
    # For approximate solve use a single midpoint profile, not entrywise unrelated coefficients.
    midboxes=boxes[:]; midpoint_effects=[mid(e) for e in boxes]
    def score(n,j,s):
     g=(n*sqrtiv(z(n-1,j)/z(n,j)) if n else 0)+(n+1)*sqrtiv(z(n+1,j)/z(n,j))
     ans=out(ap(s)*(n+F(1,2))-C*g/2)
     return ans if j==0 else -ans
    m=3
    saved=boxes;boxes=[IV(v) for v in midpoint_effects];sm=[IV(mid(s)) for s in ss]
    dd,oo=coef(m,sm);dd=list(map(mid,dd));oo=list(map(mid,oo));qq=[F(3*n-1) for n in range(m+1)]
    uq=tridiagonal_solve(dd,oo,qq);trials=[];lams=[]
    def dot(v,w):return sum(a*b for a,b in zip(v,w))
    for j in range(2):
     b=[mid(score(n,j,sm[j])) for n in range(m+1)];un=tridiagonal_solve(dd,oo,b);lam=dot(qq,un)/dot(qq,uq)
     w=[F(((a-lam*b)*(1<<110)).__floor__(),1<<110) for a,b in zip(un,uq)]
     w[0]=sum(qq[n]*w[n] for n in range(1,m+1));trials.append(w);lams.append(F((lam*(1<<110)).__floor__(),1<<110))
    boxes=saved
    # Full moments, using complement ratio1/2 from n>=2 for sharper tail.
    hr=F(1,16);start=5
    r0lo=sum((n+F(1,2))*z(n,1).a for n in range(start))
    r0hi=sum((n+F(1,2))*z(n,1).b for n in range(start))+z(start,1).b*((start+F(1,2))/(1-hr)+hr/(1-hr)**2)
    rs=[IV(F(5,6)-r0hi,F(5,6)-r0lo),IV(r0lo,r0hi)]
    ds=[out(rs[j]*app(ss[j])) for j in range(2)]
    dd,oo=coef(m+1,ss)
    def matvec(d,a,v):return [out(d[n]*v[n]+(a[n-1]*v[n-1] if n else 0)+(a[n]*v[n+1] if n+1<len(v) else 0)) for n in range(len(v))]
    Ms=[absiv(ap(ss[0]))+C*(1+1/(4*sqrtq(L,bits=300).a)),absiv(ap(ss[1]))+C*(1/SIG+RHO/4)]
    epsj=[]
    for j in range(2):
     lv=matvec(dd,oo,trials[j]+[F(0)]); rr=[out(score(n,j,ss[j])-lams[j]*(3*n-1)-lv[n]) for n in range(m+2)]
     head=head_norm(rr,[z(n,1).b for n in range(m+2)])
     yt=z(start,1).b*((start+1)/(1-hr)+hr/(1-hr)**2)
     tailerr=(Ms[j]+3*abs(lams[j]))**2*yt
     epsj.append((head+tailerr)/ky)
    def form(v,w):
     a=v+[F(0)];b=w+[F(0)];ans=IV(0)
     for n in range(m+1):
      for j in range(2):ans=out(ans+h(n,j,ss[j])*(a[n]/z(n,j)-a[n+1]/z(n+1,j))*(b[n]/z(n,j)-b[n+1]/z(n+1,j)))
     return ans
    scores=[[score(n,j,ss[j]) for n in range(m+1)] for j in range(2)]
    tt=[[out(dot(scores[i],trials[j])+dot(scores[j],trials[i])-form(trials[i],trials[j])) for j in range(2)] for i in range(2)]
    delta=sum(epsj)
    S=[[out((ds[i] if i==j else IV(0))-tt[i][j]-(delta if i==j else 0)) for j in range(2)] for i in range(2)]
    margin=min(S[i][i].a-absiv(S[i][1-i]) for i in range(2))
    assert margin>F(1,3)
    assert epsj[0]>0 and epsj[1]>0
    assert 1-boxes[2].b>F(6534,100000) and 1-boxes[2].a<F(6536,100000)
    assert all(d.b<30 for d in ds)
    assert all(S[i][i].a-F(1,100)*ds[i].b>absiv(S[i][1-i]) for i in range(2))
    assert kappa>F(1,50)
    assert all(d.a>F(3,4) for d in ds)
    pair=lambda v:[str(v.a),str(v.b)]
    return dict(tail_K_lower=str(knlo),tail_K_upper=str(knhi),center_dual=str(dual(CENTER,u).a),upper=str(U),coordinate_boxes=[pair(v) for v in boxes],squeeze_boxes=[pair(v) for v in ss],
      uniform_gap=str(eps),kappa=str(kappa),kappa_y=str(ky),D=[pair(v) for v in ds],
      schur_lower=[[pair(v) for v in row] for row in S],margin=str(margin),
      eta='1/100',weight_growth='1/20000',squeeze_growth='3/1600',
      trial_support_last=m,trials=[list(map(str,v)) for v in trials],
      residual_squared_upper=list(map(str,epsj)),junction_included=m+1,tail_from=start,
      envelope_global=['e>=3/20','f_next>=f/9','f_next<=4*f/9'],
      envelope_tail='f_next<=f/4 for n>=2')
def initial_rectangles():
 g=exterior.G;c=CENTER;R=BASIN_RADIUS
 cuts=[[g[0],c[0]-R,c[0]+R,g[1]],[g[2],c[1]-R,c[1]+R,g[3]]]
 assert all(a<b for cc in cuts for a,b in zip(cc,cc[1:]))
 return {str(i)+str(j):(cuts[0][i],cuts[0][i+1],cuts[1][j],cuts[1][j+1]) for i in range(3) for j in range(3)}
def split(q):
 a=0 if 8*(q[1]-q[0])**2>16*(q[3]-q[2])**2 else 2
 m=(q[a]+q[a+1])/2;l=list(q);r=list(q);l[a+1]=m;r[a]=m
 return tuple(l),tuple(r)
def partition(keys):
 assert len(keys)==len(set(keys)), 'duplicate leaf'
 todo=set(keys);out={}
 def visit(key,q):
  if key in todo:todo.remove(key);out[key]=q;return
  assert any(k.startswith(key) for k in todo), 'missing exterior branch'
  left,right=split(q);visit(key+'0',left);visit(key+'1',right)
 for key,q in initial_rectangles().items():
  if key!='11':visit(key,q)
 assert not todo,'unreachable or overlapping leaf'
 return out

def free_inputs(q,key):
 center=[(q[0]+q[1])/2,(q[2]+q[3])/2]
 row=profile_at(*[(center[j]-CENTER[j])/RADIUS for j in range(2)])
 # Clipping is legitimate ONLY as arbitrary strictly positive dual data.
 row['f']=[str(max(F(1,10**90),min(1-F(1,10**90),F(v)))) for v in row['f']]
 yield center,seed_inputs(row["f"])[2]
 for prefix,ff in FREE_PROFILE_SEEDS.items():
  if key.startswith(prefix):yield center,seed_inputs(ff)[2]

def exterior_certificate():
 prior_cert=inherited();U=F(prior_cert['feasible_energy_upper']);rects=partition(LEAF_KEYS);margins=[]
 for key,q in rects.items():
  val=max(dual(c,u).a for c,u in free_inputs(q,key))
  margin=val-taylor_loss((q[1]-q[0])/2,(q[3]-q[2])/2)-U
  assert margin>0,('nonpositive exterior margin',key,str(margin))
  margins.append(margin)
 return dict(exterior_leaves=len(rects),free_profile_seeds=len(FREE_PROFILE_SEEDS),minimum_margin=str(min(margins)),root_rectangle=list(map(str,exterior.G)),basin_radius=str(BASIN_RADIUS),shared_faces_included=True)

def controls(fault=None):
 cs={};ck=lambda k,v:cs.__setitem__(k,bool(v))
 h1,h0=F(1,500),F(1,700)
 ck('stationary_Taylor_corner',taylor_loss(h1,h0,fault)==(16*h1*h1+32*h0*h0)/2)
 r=BASIN_RADIUS;loss=capture_loss(r,fault)
 ck('center_transfer_quadratic',loss==(16+32)*r*r/2)
 rects=partition(LEAF_KEYS);area=sum(exterior.area(q) for q in rects.values())+4*r*r
 ck('complete_exact_area',area==exterior.area(exterior.G))
 # Independence from a computed optimizer: any positive free slopes work.
 ff=profile_at(F(0),F(0))['f']
 if fault=='positive_slope':ff[0]=str(-F(ff[0]))
 try:
  _,_,u=seed_inputs(ff);valid=all(v>0 for row in u for v in row)
 except AssertionError:valid=False
 ck('actual_slope_admissibility',valid)
 return cs

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--write',action='store_true');a=ap.parse_args()
 cs=controls();assert all(cs.values());basin=basin_certificate();ext=exterior_certificate()
 faults={f:[k for k,v in controls(f).items() if not v] for f in ['Taylor','center_transfer','positive_slope']}
 try:partition(LEAF_KEYS[:-1])
 except AssertionError as e:faults['missing_exterior_leaf']=[str(e)]
 else:raise AssertionError('missing leaf not detected')
 assert all(faults.values())
 lower=F(basin['center_dual'])-capture_loss(RADIUS);upper=F(basin['upper']);assert 0<upper-lower<F(25,10**28)
 cert=dict(basin=basin,exterior=ext,global_energy_lower=str(lower),global_energy_upper=str(upper),global_bracket_width=str(upper-lower),unique_global_minimizer=True)
 deps=['tests/channel-swings/k2210_detector_stationary_certificate_probe.py','tests/channel-swings/k2213_detector_convex_uniqueness_probe.py','tests/channel-swings/k2216_detector_exterior_certificate_probe.py','lab/process/k2210-detector-stationary-certificate.json','lab/process/k2213-detector-convex-uniqueness.json','explorations/conditional-build/k2219-detector-global-capture-2026-10-28.md']
 report=dict(result_id='K2219',status='unique_global_half_contrast_detector_minimizer',checks=cs,fault_failures=faults,certificate=cert,dependency_sha256={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in deps},probe_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),evidence_kinds='Fresh all-tail stationary capture and outward Schur; complete exact221-leaf dual exterior with free positive inputs; universal convex-chord proof and inherited existence. No optimizer convergence assumption, apparatus or GU physics credit.')
 dst=ROOT/'lab/process/k2219-detector-global-capture.json'
 if a.write:dst.write_text(json.dumps(report,indent=2)+'\n')
 else:assert json.loads(dst.read_text())==report
 print(json.dumps(dict(result='K2219',controls=len(cs),faults=len(faults),leaves=ext['exterior_leaves'],margin_display=float(F(basin['margin'])),exterior_margin_display=float(F(ext['minimum_margin'])),energy_display=float(upper),width_display=float(upper-lower))))
if __name__=='__main__':main()
